def min_absolute_difference(nums: List[int], k: int) -> int:
    """Minimize the distance from k to a contiguous subarray's bitwise OR."""
    # The distinct ORs of subarrays ending at a given index are at most the
    # number of bits in the input values: each extension can only set bits.
    ending = set()
    best = float("inf")
    for value in nums:
        current = {value}
        current.update(value | previous for previous in ending)
        for result in current:
            best = min(best, abs(result - k))
            if best == 0:
                return 0
        ending = current
    return int(best)"}
